// Constantes injectées par Vite au build (voir `define` dans vite.config.ts).
// Elles sont remplacées littéralement dans le bundle : rien n'est lu au
// démarrage, il n'y a donc aucun coût à l'exécution.

/** Date du build, au format ISO 8601 (UTC). */
declare const __BUILD_TIME__: string

/** Commit git court à partir duquel le build a été fait, ou 'inconnu'. */
declare const __BUILD_COMMIT__: string
